ERP_CHECKOUT_UX_B64_6

    ROUTE_BLOCK_FILE="$(
        mktemp "${TMPDIR:-/tmp}/linxen_checkout_ux_routes.XXXXXX"
    )"

    cat > "$ROUTE_BLOCK_FILE" <<'ROUTE_BLOCK'
/* AI_PATCH_LINXEN_GUEST_ONE_PAGE_CHECKOUT_UX_V1_START */
Route::prefix('commerce/v2/sites/{site}')
    ->middleware([
        \App\Http\Middleware\Commerce\CommerceApiExceptionBoundary::class,
        \App\Http\Middleware\Commerce\ResolveCommerceSiteContext::class,
    ])
    ->group(function () {
        Route::get('/checkout/capabilities', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
            'capabilities',
        ]);

        Route::get('/checkout/locations', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
            'locations',
        ]);

        Route::get('/checkout/locations/{location}/wards', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
            'wards',
        ])->whereNumber('location');

        Route::post('/checkout/guest-session', [
            \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
            'guestSession',
        ]);

        Route::middleware([
            \App\Http\Middleware\Commerce\ResolveCommerceCustomerSession::class,
        ])->group(function () {
            Route::post('/customer/checkout-address', [
                \App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
                'address',
            ]);
        });
    });
/* AI_PATCH_LINXEN_GUEST_ONE_PAGE_CHECKOUT_UX_V1_END */
ROUTE_BLOCK

    export COMMERCE_API_ROUTES='routes/api.php'
    export COMMERCE_CHECKOUT_UX_ROUTE_BLOCK_FILE="$ROUTE_BLOCK_FILE"

    php <<'PHP'
<?php

$path = getenv('COMMERCE_API_ROUTES');
$blockPath = getenv(
    'COMMERCE_CHECKOUT_UX_ROUTE_BLOCK_FILE'
);
$source = file_get_contents($path);
$block = file_get_contents($blockPath);

if (! is_string($source) || ! is_string($block)) {
    fwrite(
        STDERR,
        "ERROR: Cannot read Commerce route source/block.\n"
    );
    exit(1);
}

$start = '/* AI_PATCH_LINXEN_GUEST_ONE_PAGE_CHECKOUT_UX_V1_START */';
$end = '/* AI_PATCH_LINXEN_GUEST_ONE_PAGE_CHECKOUT_UX_V1_END */';
$startCount = substr_count($source, $start);
$endCount = substr_count($source, $end);

if ($startCount !== $endCount || $startCount > 1) {
    fwrite(
        STDERR,
        "ERROR: Checkout UX route marker imbalance.\n"
    );
    exit(1);
}

if ($startCount === 1) {
    $pattern = '/'
        . preg_quote($start, '/')
        . '.*?'
        . preg_quote($end, '/')
        . '/s';
    $source = preg_replace(
        $pattern,
        '',
        $source,
        1,
        $count
    );

    if (! is_string($source) || $count !== 1) {
        fwrite(
            STDERR,
            "ERROR: Cannot remove old checkout UX route block.\n"
        );
        exit(1);
    }
}

$patched = rtrim($source)
    . "\n\n"
    . trim($block)
    . "\n";

$written = file_put_contents($path, $patched);

if ($written === false || $written !== strlen($patched)) {
    fwrite(
        STDERR,
        "ERROR: Cannot write routes/api.php.\n"
    );
    exit(1);
}
PHP

    rm -f "$ROUTE_BLOCK_FILE"

    for FILE in \
      'app/Services/Commerce/CommerceCustomerAuthService.php' \
      'app/Services/Commerce/CommerceCheckoutIdentityService.php' \
      'app/Http/Middleware/Commerce/ResolveCommerceCustomerSession.php' \
      'app/Http/Controllers/Api/Commerce/V2/CommerceCheckoutIdentityController.php' \
      'app/Console/Commands/Commerce/BootstrapCheckoutUxCommand.php' \
      'app/Console/Commands/Commerce/AuditCheckoutUxCommand.php' \
      'routes/api.php'
    do
        php -l "$FILE"
    done

    artisan_safe optimize:clear

    php <<'PHP'
<?php

require getcwd() . '/vendor/autoload.php';

$app = require getcwd() . '/bootstrap/app.php';

$app->make(
    Illuminate\Contracts\Console\Kernel::class
)->bootstrap();

$expected = [
    'api/commerce/v2/sites/{site}/checkout/capabilities',
    'api/commerce/v2/sites/{site}/checkout/locations',
    'api/commerce/v2/sites/{site}/checkout/locations/{location}/wards',
    'api/commerce/v2/sites/{site}/checkout/guest-session',
    'api/commerce/v2/sites/{site}/customer/checkout-address',
];

$found = [];

foreach ($app['router']->getRoutes() as $route) {
    if (in_array($route->uri(), $expected, true)) {
        $found[$route->uri()] = true;
    }
}

$missing = array_values(
    array_diff($expected, array_keys($found))
);

if ($missing !== []) {
    fwrite(
        STDERR,
        'ERROR: Missing ERP checkout UX routes: '
            . implode(', ', $missing)
            . PHP_EOL
    );
    exit(1);
}

$controllers = [
    App\Http\Controllers\Api\Commerce\V2\CommerceCheckoutIdentityController::class,
];

foreach ($controllers as $controller) {
    $resolved = $app->make($controller);

    if (! $resolved instanceof $controller) {
        fwrite(
            STDERR,
            "ERROR: Controller resolution failed: {$controller}\n"
        );
        exit(1);
    }
}

echo "ERP_CHECKOUT_UX_ROUTE_DISCOVERY=PASS\n";
echo "ERP_CHECKOUT_UX_CONTROLLER_RESOLUTION=PASS\n";
echo "ERP_PATCH_DB_MUTATION=NONE\n";
echo "ERP_PATCH_PROVIDER_CALL=NONE\n";
PHP

    artisan_safe list --raw \
      | grep -E \
        '^commerce:(bootstrap-checkout-ux|audit-checkout-ux)([[:space:]]|$)' \
      >/dev/null

    trap - ERR

    printf '%s\n' \
      'LINXEN_GUEST_ONE_PAGE_CHECKOUT_ERP_SOURCE_PATCH_V1_3=PASS'
    printf '%s\n' 'MIGRATION=NONE'
    printf '%s\n' 'GUEST_CHECKOUT_GATE=DB_BACKED'
    printf '%s\n' 'OTP_CHECKOUT_GATE=IMPLEMENTED_DEFAULT_OFF'
    printf '%s\n' 'SMS_PROVIDER_CALL=NONE'
    printf '%s\n' 'ORDER_ACCEPT_GATE=UNCHANGED'
    printf '%s\n' 'PROVIDER_WRITE_GATE=UNCHANGED'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi

if [ "$TARGET" = 'storefront' ]; then
    REQUIRED=(
        'app/Exceptions/CommerceV2/CommerceV2ClientException.php'
        'app/Services/CommerceV2/CheckoutQuoteSessionService.php'
        'app/Services/CommerceV2/OrderIdempotencySessionService.php'
        'app/Services/CommerceV2/AttributionSessionService.php'
        'app/Http/Controllers/CommerceV2/CartController.php'
        'routes/commerce_v2.php'
        'resources/views/commerce_v2/layouts/app.blade.php'
        'public/commerce-v2/commerce.css'
        'public/commerce-v2/commerce.js'
    )

    for FILE in "${REQUIRED[@]}"; do
        test -f "$FILE" || {
            printf 'ERROR: Missing Storefront dependency: %s\n' \
              "$FILE" >&2
            exit 1
        }
    done

    FILES=(
        'app/Services/CommerceV2/ErpCommerceClient.php'
        'app/Services/CommerceV2/SessionCartService.php'
        'app/Services/CommerceV2/CustomerSessionService.php'
        'app/Services/CommerceV2/OrderAccessSessionService.php'
        'app/Services/CommerceV2/OnePageCheckoutSessionService.php'
        'app/Http/Controllers/CommerceV2/CheckoutController.php'
        'app/Http/Controllers/CommerceV2/OrderController.php'
        'app/Http/Controllers/CommerceV2/AccountController.php'
        'app/Console/Commands/CommerceV2CheckoutFoundationSmokeCommand.php'
        'routes/commerce_v2.php'
        'resources/views/commerce_v2/layouts/app.blade.php'
        'resources/views/commerce_v2/pages/cart.blade.php'
        'resources/views/commerce_v2/pages/checkout.blade.php'
        'resources/views/commerce_v2/pages/checkout_confirm.blade.php'
        'resources/views/commerce_v2/pages/orders.blade.php'
        'resources/views/commerce_v2/pages/order.blade.php'
        'resources/views/commerce_v2/pages/account.blade.php'
        'resources/views/commerce_v2/pages/order_success.blade.php'
        'public/commerce-v2/commerce.css'
        'public/commerce-v2/commerce.js'
    )

    for FILE in "${FILES[@]}"; do
        backup_file "$FILE"
    done

