dOG7k24ga2hvIHbDoCBnaGkgbmjhuq1uIMSRxqFuLi4uJzsKICAgIH0pOwp9KSgpOwo=
SF_CHECKOUT_UX_B64_20

    for FILE in \
      app/Services/CommerceV2/ErpCommerceClient.php \
      app/Services/CommerceV2/SessionCartService.php \
      app/Services/CommerceV2/CustomerSessionService.php \
      app/Services/CommerceV2/OrderAccessSessionService.php \
      app/Services/CommerceV2/OnePageCheckoutSessionService.php \
      app/Http/Controllers/CommerceV2/CheckoutController.php \
      app/Http/Controllers/CommerceV2/OrderController.php \
      app/Http/Controllers/CommerceV2/AccountController.php \
      app/Console/Commands/CommerceV2CheckoutFoundationSmokeCommand.php \
      routes/commerce_v2.php
    do
        php -l "$FILE"
    done

    grep -Fq -- \
      'data-lxv2-one-page-checkout' \
      resources/views/commerce_v2/pages/checkout.blade.php

    grep -Fq -- \
      'Đặt hàng thành công' \
      resources/views/commerce_v2/pages/order_success.blade.php

    grep -Fq -- \
      'public function checkoutCapabilities(): array' \
      app/Services/CommerceV2/ErpCommerceClient.php

    grep -Fq -- \
      "'/checkout/capabilities'" \
      app/Services/CommerceV2/ErpCommerceClient.php

    grep -Fq -- \
      "->name('checkout.place_order')" \
      routes/commerce_v2.php

    artisan_safe optimize:clear
    artisan_safe view:cache
    artisan_safe view:clear
    artisan_safe commerce-v2:checkout-foundation-smoke

    php <<'PHP'
<?php

require getcwd() . '/vendor/autoload.php';

$app = require getcwd() . '/bootstrap/app.php';

$app->make(
    Illuminate\Contracts\Console\Kernel::class
)->bootstrap();

$expected = [
    'commerce.v2.checkout.index',
    'commerce.v2.checkout.place_order',
    'commerce.v2.checkout.wards',
    'commerce.v2.orders.success',
    'commerce.v2.orders.index',
    'commerce.v2.orders.show',
];

foreach ($expected as $routeName) {
    if (! Illuminate\Support\Facades\Route::has($routeName)) {
        fwrite(
            STDERR,
            "ERROR: Missing Storefront route: {$routeName}\n"
        );
        exit(1);
    }
}

$controllers = [
    App\Http\Controllers\CommerceV2\CheckoutController::class,
    App\Http\Controllers\CommerceV2\OrderController::class,
    App\Http\Controllers\CommerceV2\AccountController::class,
];

foreach ($controllers as $controller) {
    $resolved = $app->make($controller);

    if (! $resolved instanceof $controller) {
        fwrite(
            STDERR,
            "ERROR: Storefront controller resolution failed: {$controller}\n"
        );
        exit(1);
    }
}

echo "STOREFRONT_CHECKOUT_UX_ROUTE_DISCOVERY=PASS\n";
echo "STOREFRONT_CHECKOUT_UX_CONTROLLER_RESOLUTION=PASS\n";
echo "LOCAL_ERP_API_CALL=NONE\n";
PHP

    trap - ERR

    printf '%s\n' \
      'LINXEN_GUEST_ONE_PAGE_CHECKOUT_STOREFRONT_SOURCE_PATCH_V1_3=PASS'
    printf '%s\n' 'STATIC_PREFLIGHT_CONTRACT=CORRECTED_GATE_AWARE_CHECKOUT_RENDER_ASSERTION'
    printf '%s\n' 'ONE_PAGE_CHECKOUT=IMPLEMENTED'
    printf '%s\n' 'QUOTE_VISIBILITY=INTERNAL'
    printf '%s\n' 'GUEST_CHECKOUT=IMPLEMENTED_DB_GATED'
    printf '%s\n' 'OTP_TRANSPORT=DISABLED_NO_PROVIDER'
    printf '%s\n' 'ORDER_SUCCESS_PAGE=IMPLEMENTED'
    printf '%s\n' 'MY_ORDERS_GUEST_SCOPE=SESSION_CREATED_ORDERS_ONLY'
    printf '%s\n' 'ORDER_ACCEPT_GATE=UNCHANGED'
    printf '%s\n' 'PROVIDER_WRITE_GATE=UNCHANGED'
    printf '%s\n' 'DB_MUTATION=NONE'
    printf '%s\n' 'NPM_BUILD=NOT_REQUIRED'
    printf '%s\n' 'V1_STOREFRONT=UNCHANGED'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi
